-- Auto-generated by matugen — do not edit by hand.
-- base16 palette + legibility helpers for Neovim, derived from the current
-- wallpaper. Consumed by ~/.config/nvim/lua/matugen.lua; regenerated on every
-- wallpaper change (see [templates.nvim] in ~/.config/matugen/config.toml).
--
-- Role choices favour legibility on the dark surface: every foreground role
-- below is a light Material role (on_surface*/accent), never a dark *_container
-- role, which would be unreadable on the dark background.
return {
  base00 = "{{ colors.surface.dark.hex }}",             -- background
  base01 = "{{ colors.surface_container_low.dark.hex }}",
  base02 = "{{ colors.surface_container.dark.hex }}",   -- cursorline / selection
  base03 = "{{ colors.outline.dark.hex }}",             -- dim accents (line numbers, delimiters)
  base04 = "{{ colors.on_surface_variant.dark.hex }}",  -- secondary text
  base05 = "{{ colors.on_surface.dark.hex }}",          -- primary text
  base06 = "{{ colors.on_surface.dark.hex }}",
  base07 = "{{ colors.on_surface.dark.hex }}",
  base08 = "{{ colors.error.dark.hex }}",
  base09 = "{{ colors.tertiary.dark.hex }}",
  base0A = "{{ colors.secondary.dark.hex }}",
  base0B = "{{ colors.tertiary.dark.hex }}",
  base0C = "{{ colors.secondary.dark.hex }}",
  base0D = "{{ colors.primary.dark.hex }}",
  base0E = "{{ colors.error.dark.hex }}",
  base0F = "{{ colors.secondary.dark.hex }}",
  comment = "{{ colors.on_surface_variant.dark.hex }}", -- legible comment colour
}
